import{_ as t,o as a,c as s,a5 as r}from"./chunks/framework.BZzouRtU.js";const d="/study/images/algorithms/sparse-sets.svg",D=JSON.parse('{"title":"スパースセットとECSのコンポーネント管理","description":"","frontmatter":{"title":"スパースセットとECSのコンポーネント管理","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"algorithms","summary":"整数IDから密な配列の位置を引き、所属判定と末尾を移す削除を定数時間で行う仕組みを調べる。","aliases":["スパースセット","sparse set","dense array","sparse array","packed array","swap-and-pop","ECS","世代付きID"]}},"headers":[],"relativePath":"algorithms/sparse-sets.md","filePath":"algorithms/sparse-sets.md"}'),o={name:"algorithms/sparse-sets.md"};function c(n,e,i,p,h,l){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="スパースセットとecsのコンポーネント管理" tabindex="-1">スパースセットとECSのコンポーネント管理 <a class="header-anchor" href="#スパースセットとecsのコンポーネント管理" aria-label="Permalink to &quot;スパースセットとECSのコンポーネント管理&quot;">​</a></h1><p>ゲーム内でエンティティID <code>2</code>、<code>7</code>、<code>4</code> が位置コンポーネントを持っているとします。毎フレーム、位置コンポーネントを持つエンティティだけを順に処理し、同時にID <code>7</code> が位置コンポーネントを持つかどうかもすぐ調べたい場面です。<strong>スパースセット</strong>では、現在使っているIDを詰めた <code>dense</code> と、IDに対応する位置を記録する <code>sparse</code> を組み合わせます。EnTTなどのECSでは、この考え方をコンポーネントの格納に使っています。<a href="https://skypjack.github.io/entt/md_docs_2md_2entity.html" target="_blank" rel="noreferrer">EnTTのコンポーネント格納とスパースセット</a></p><h2 id="idと配列の位置を行き来する" tabindex="-1">IDと配列の位置を行き来する <a class="header-anchor" href="#idと配列の位置を行き来する" aria-label="Permalink to &quot;IDと配列の位置を行き来する&quot;">​</a></h2><p><code>dense[i]</code> は位置 <code>i</code> にいるID、<code>sparse[id]</code> はIDがいるはずの位置です。使っていないIDの <code>sparse</code> に以前の位置が残っていても、そこに現在どのIDがいるかを見れば区別できます。IDが属している条件は、<code>sparse[id]</code> が <code>dense</code> の有効な位置にあり、かつ <code>dense[sparse[id]] == id</code> であることです。ID自体の範囲も先に調べます。</p><figure class="study-figure"><img src="'+d+'" alt="削除前のdenseは2、7、4。sparseのID7とID4はそれぞれ位置1と2を指す。ID7を削除すると、末尾のID4が位置1に移り、sparseのID4も1になる。sparseのID7には1が残るが、denseの位置1はID4なのでID7は含まれない。" width="760" height="346" loading="lazy"><figcaption>ID 7を消すと、ID 4が移動します。所属判定には移動先から元のIDに戻れるかも使います。<a href="/study/images/algorithms/sparse-sets.svg" target="_blank" rel="noopener noreferrer">配列の図を拡大</a></figcaption></figure><h2 id="追加と、順序を保たない削除" tabindex="-1">追加と、順序を保たない削除 <a class="header-anchor" href="#追加と、順序を保たない削除" aria-label="Permalink to &quot;追加と、順序を保たない削除&quot;">​</a></h2><p>追加では新しいIDを <code>dense</code> の末尾に置き、<code>sparse</code> にその位置を書きます。中間を削除する例では、空いた位置に末尾のIDを移し、移動したIDの <code>sparse</code> を更新してから、<code>dense</code> の末尾を取り除きます。この方法を <strong>swap-and-pop</strong> と呼びます。コンポーネント本体も同じ並びで格納する実装では、移動したIDと対応する値を一緒に移します。処理中に密な配列の位置を保持している場合、その位置が別のIDを指すようになります。</p><table tabindex="0"><thead><tr><th>操作</th><th>このモデルのコスト</th></tr></thead><tbody><tr><td>IDが含まれるか調べる</td><td><code>O(1)</code></td></tr><tr><td>追加する</td><td>領域確保済みなら <code>O(1)</code>。幾何的に拡張する動的配列なら償却 <code>O(1)</code></td></tr><tr><td>削除する</td><td>順序を維持せず、固定サイズのIDを移すなら <code>O(1)</code></td></tr><tr><td>使っているIDをすべて列挙する</td><td><code>O(n)</code>。<code>n</code> は現在の件数</td></tr></tbody></table><p>単純な <code>sparse</code> 配列の要素数は、格納している件数よりもIDの範囲に依存します。上限が大きく、使うIDが飛び飛びなら、必要なページだけに表を作る方法や、IDから位置を引く部分にハッシュ表を使う方法があります。EnTTにはページ分割されたスパース配列と複数の削除方式があり、ここで使った古い添字を残すモデルとは実装上の細部が異なります。<a href="https://skypjack.github.io/entt/sparse__set_8hpp_source.html" target="_blank" rel="noreferrer">EnTTのスパース配列の実装</a> · <a href="/study/algorithms/hash-tables.html">ハッシュ表</a></p><p>ECSでIDを再発行する場合、同じ数値のスロットが別のエンティティに使われます。古いハンドルを識別するには、スロットに加えて世代の一致を確認します。密に並べて走査すること、削除時の順序、参照の安定性はそれぞれ独立した設計条件です。<a href="/study/algorithms/generational-handles.html">世代付きハンドル</a> · <a href="/study/game/patterns/component-and-ecs.html">ECSのコンポーネント管理</a> · <a href="/study/algorithms/arrays-and-dynamic-arrays.html">動的配列の再確保と参照</a></p><p><a href="/study/practice/algorithms/sparse-set-observation.html">IDを追加・削除して二つの配列を観察する</a></p>',11)])])}const I=t(o,[["render",c]]);export{D as __pageData,I as default};
